#!/usr/bin/env node
/**
 * Compiles source files into dist/ bundles for the npm package.
 *
 * Outputs:
 *   dist/setup-bundle.md      — all setup skill content inlined; agent reads this to run setup
 *   dist/workflow-bundle.md   — full src/workflow/ tree in FILE markers; agent expands post-setup
 *
 * Also populates:
 *   src/assets/adapters/      — rendered adapter shims (copied from src/adapters/ source)
 *   validators/               — validator scripts needed during setup (copied from src/workflow/validators/)
 *   workflow/schemas/         — schema snapshot for dev workspace validators (copied from src/workflow/schemas/)
 */

import { readFileSync, writeFileSync, mkdirSync, readdirSync, statSync, copyFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));

function read(rel) {
  return readFileSync(join(root, rel), 'utf8');
}

function write(rel, content) {
  const full = join(root, rel);
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, content, 'utf8');
  console.log(`wrote   ${rel}`);
}

function copyFile(src, dest) {
  const destFull = join(root, dest);
  mkdirSync(dirname(destFull), { recursive: true });
  copyFileSync(join(root, src), destFull);
  console.log(`copied  ${dest}`);
}

function walkFiles(dir, base = dir) {
  const results = [];
  for (const name of readdirSync(join(root, dir)).sort()) {
    const rel = join(dir, name);
    const stat = statSync(join(root, rel));
    if (stat.isDirectory()) {
      results.push(...walkFiles(rel, base));
    } else {
      results.push(rel.replaceAll('\\', '/'));
    }
  }
  return results;
}

// ─── setup-bundle.md ───────────────────────────────────────────────────────

const setupSections = [
  '<!-- compiled from src/setup/ sources — agent reads this to run the setup skill -->',
  '<!-- do not edit this file directly; edit src/setup/SKILL.md and src/setup/references/ then re-run build-bundle.mjs -->',
  '',
  read('src/setup/SKILL.md').trim(),
];

const refDir = join(root, 'src/setup/references');
const refFiles = readdirSync(refDir).filter(f => f.endsWith('.md')).sort();
for (const name of refFiles) {
  const content = readFileSync(join(refDir, name), 'utf8').trim();
  setupSections.push('', '---', '', content);
}

write('dist/setup-bundle.md', setupSections.join('\n') + '\n');

// ─── workflow-bundle.md ────────────────────────────────────────────────────
// src/workflow/config/ is excluded from the bundle — agent-behavior.yaml ships via
// src/assets/ (static copy below), and per-consumer configs are written by the setup skill.

const WORKFLOW_EXCLUDES = new Set(['src/workflow/config']);
const workflowFiles = walkFiles('src/workflow').filter(rel =>
  !rel.endsWith('.gitkeep') &&
  !WORKFLOW_EXCLUDES.has(rel) &&
  ![...WORKFLOW_EXCLUDES].some(exc => rel.startsWith(exc + '/'))
);

const bundleLines = [
  '<!-- compiled from src/workflow/ sources — agent expands FILE blocks into consumer repo as workflow/ -->',
  '<!-- do not edit this file directly; edit source files under src/workflow/ then re-run build-bundle.mjs -->',
  '',
];

for (const rel of workflowFiles) {
  const content = read(rel);
  bundleLines.push(`<!-- FILE: ${rel.replace(/^src\/workflow\//, 'workflow/')} -->`);
  bundleLines.push(content.trimEnd());
  bundleLines.push(`<!-- END FILE -->`);
  bundleLines.push('');
}

write('dist/workflow-bundle.md', bundleLines.join('\n') + '\n');

// ─── src/assets/workflow/config/agent-behavior.yaml ──────────────────────
// Sync the shipped invariant from src/workflow/config/ to src/assets/ so consumers
// receive it as a static file (config/ is excluded from the workflow bundle above).

copyFile('src/workflow/config/agent-behavior.yaml', 'src/assets/workflow/config/agent-behavior.yaml');

// ─── src/assets/adapters/ ─────────────────────────────────────────────────

for (const rel of walkFiles('src/adapters')) {
  const dest = rel.replace(/^src\/adapters\//, 'src/assets/adapters/');
  copyFile(rel, dest);
}

// ─── validators/ (setup-time copies) ──────────────────────────────────────

const setupValidators = ['lib.mjs', 'check-config.mjs', 'check-setup-complete.mjs'];
for (const name of setupValidators) {
  copyFile(`src/workflow/validators/${name}`, `validators/${name}`);
}

// ─── workflow/schemas/ (dev workspace snapshot) ───────────────────────────
// Keeps the dev workspace in sync so runtime validators can resolve schemas.

for (const rel of walkFiles('src/workflow/schemas')) {
  const dest = rel.replace(/^src\/workflow\/schemas\//, 'workflow/schemas/');
  copyFile(rel, dest);
}

console.log('\nbuild-bundle: ok');
